/* Knowledge Graph viewer — read-only visualization (Phase: Engineering Knowledge Hub).
 * Vanilla JS, no dependencies. Fetches /data/knowledge-graph.json (generated by
 * scripts/build-knowledge-graph.cjs during the Hugo build) and renders an
 * interactive concept/post explorer. Degrades to the <noscript> list if JS is off.
 */
(function () {
  'use strict';
  var root = document.getElementById('kg-root');
  if (!root) return;

  function el(tag, attrs, text) {
    var n = document.createElement(tag);
    if (attrs) Object.keys(attrs).forEach(function (k) { n.setAttribute(k, attrs[k]); });
    if (text != null) n.textContent = text;
    return n;
  }

  function renderError(msg) {
    root.innerHTML = '';
    root.appendChild(el('p', { class: 'kg-error' }, msg));
  }

  function buildUi(data) {
    var nodes = data.nodes || [];
    var edges = data.edges || [];
    var concepts = nodes.filter(function (n) { return n.type === 'concept'; });
    var posts = nodes.filter(function (n) { return n.type === 'post'; });

    root.innerHTML = '';

    var meta = el('p', { class: 'kg-meta' },
      'Knowledge Graph: ' + posts.length + ' posts, ' + concepts.length +
      ' concepts, ' + edges.length + ' relations.');
    root.appendChild(meta);

    // Concept filter buttons.
    var filterBar = el('div', { class: 'kg-filters' });
    var allBtn = el('button', { class: 'kg-filter kg-active', 'data-concept': '' }, 'All');
    filterBar.appendChild(allBtn);
    concepts.forEach(function (c) {
      filterBar.appendChild(el('button', { class: 'kg-filter', 'data-concept': c.id }, c.label || c.id));
    });
    root.appendChild(filterBar);

    var list = el('div', { class: 'kg-list' });
    root.appendChild(list);

    function relatedPosts(conceptId) {
      if (!conceptId) return posts;
      var related = edges
        .filter(function (e) { return e.target === conceptId && e.source; })
        .map(function (e) { return e.source; });
      return posts.filter(function (p) {
        return related.indexOf(p.id) !== -1 || (p.concepts && p.concepts.indexOf(conceptId) !== -1);
      });
    }

    function show(conceptId) {
      list.innerHTML = '';
      var shown = relatedPosts(conceptId);
      if (shown.length === 0) {
        list.appendChild(el('p', {}, 'No posts linked to this concept yet.'));
        return;
      }
      shown.forEach(function (p) {
        var item = el('div', { class: 'kg-item' });
        var a = el('a', { href: p.url || ('/' + p.id + '/') }, p.label || p.id);
        item.appendChild(a);
        if (p.date) item.appendChild(el('span', { class: 'kg-date' }, ' · ' + p.date.slice(0, 10)));
        list.appendChild(item);
      });
    }

    filterBar.addEventListener('click', function (ev) {
      var btn = ev.target.closest('.kg-filter');
      if (!btn) return;
      filterBar.querySelectorAll('.kg-filter').forEach(function (b) { b.classList.remove('kg-active'); });
      btn.classList.add('kg-active');
      show(btn.getAttribute('data-concept'));
    });

    show('');
  }

  fetch('/data/knowledge-graph.json', { cache: 'no-cache' })
    .then(function (r) { if (!r.ok) throw new Error('HTTP ' + r.status); return r.json(); })
    .then(buildUi)
    .catch(function (e) { renderError('Could not load knowledge graph data: ' + e.message); });
})();
